import { Box, Flex } from "@chakra-ui/react";
import type { ProseSection } from "../../types";
import { ConditionHeader } from "./ConditionHeader";
import { type ConditionMemory } from "./ConditionTag";
import { type ReferenceIndex } from "./references";
import { SkillMarkdown } from "./SkillMarkdown";

interface ProseSegmentsProps {
  readonly section: ProseSection;
  readonly references: ReferenceIndex;
  readonly evaluatedConditions: Record<string, boolean> | undefined;
  readonly memory: ConditionMemory;
}

export function ProseSegments({
  section,
  references,
  evaluatedConditions,
  memory,
}: ProseSegmentsProps) {
  return (
    <Flex direction="column" gap="3">
      {section.segments.map((segment, segmentIndex) => {
        const conditionMet = segment.condition
          ? evaluatedConditions?.[segment.condition]
          : undefined;

        if (segment.condition === null) {
          return (
            <Box
              // Segments have no ids; index within the section is stable per catalog load.

              key={segmentIndex}
              data-testid="skill-prose-segment"
            >
              <SkillMarkdown text={segment.text} references={references} memory={memory} />
            </Box>
          );
        }

        return (
          <Flex
            // Segments have no ids; index within the section is stable per catalog load.

            key={segmentIndex}
            direction="column"
            gap="2.5"
            bg={conditionMet ? "bg.info" : "bg.subtle"}
            borderWidth={conditionMet ? "1px" : 0}
            borderColor="border.info"
            borderRadius="2xl"
            p="4"
            data-testid="skill-prose-segment"
            data-condition-met={String(conditionMet ?? "unknown")}
          >
            <ConditionHeader condition={segment.condition} memory={memory} />
            <SkillMarkdown text={segment.text} references={references} memory={memory} />
          </Flex>
        );
      })}
    </Flex>
  );
}
